        raise Exception("Invalid URL provided.")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve data from API: {e}")
    if not data:
        raise Exception("Empty data received from API.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Failed to convert data to DataFrame: {e}")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical data available for correlation heatmap.")
    corr_matrix = numeric_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr_matrix, annot=True, fmt=".2f", cmap='coolwarm', ax=ax)
    ax.set_title("Correlation Heatmap")
    return df, ax
